async function solveRound(expectedRound) {
  const memory = new Map();
  let moves = 0;
  while (await page.locator('#roundValue').evaluate(el => Number(el.textContent.split('/')[0].trim())) === expectedRound && await page.locator('#victoryPanel').isHidden()) {
    assert.ok(moves++ < 100, `round ${expectedRound} should complete without hanging`);
    const cards = page.locator('.memory-card');
    const firstIndex = await cards.evaluateAll(all => all.findIndex(card => card.getAttribute('aria-pressed') === 'false' && !card.disabled));
    if (firstIndex < 0) {
      await page.waitForFunction((round) => {
        const value = Number(document.querySelector('#roundValue').textContent.split('/')[0].trim());
        return value !== round || !document.querySelector('#victoryPanel').hidden;
      }, expectedRound, { timeout: 5000 });
      break;
    }

    await cards.nth(firstIndex).click();
    const firstIcon = await cards.nth(firstIndex).locator('.card-face').innerText();
    const available = await cards.evaluateAll(all => all.map((card, index) => ({
      index,
      hidden: card.getAttribute('aria-pressed') === 'false' && !card.disabled,
    })));
    let partner = available.find(card => card.index !== firstIndex && card.hidden && memory.get(card.index) === firstIcon)?.index;
    if (partner === undefined) partner = available.find(card => card.index !== firstIndex && card.hidden && !memory.has(card.index))?.index;
    if (partner === undefined) partner = available.find(card => card.index !== firstIndex && card.hidden)?.index;
    assert.ok(partner !== undefined, 'must have a second hidden card');

    await cards.nth(partner).click();
    const secondIcon = await cards.nth(partner).locator('.card-face').innerText();
    memory.set(firstIndex, firstIcon);
    memory.set(partner, secondIcon);
    if (firstIcon !== secondIcon) {
      await page.waitForFunction(() => [...document.querySelectorAll('.memory-card')].some(card => card.getAttribute('aria-pressed') === 'false' && !card.disabled), { timeout: 3000 });
    }
  }
}

